import '../app/studygram_app.dart';
import 'parser.dart';

class UploadScreen extends ConsumerStatefulWidget {const UploadScreen({super.key});@override ConsumerState<UploadScreen> createState()=>_UploadScreenState();}
class _UploadScreenState extends ConsumerState<UploadScreen>{bool busy=false;String status='Select your lecture files to create study posts.';
 Future<void> pick()async{final result=await FilePicker.platform.pickFiles(allowMultiple:true,type:FileType.custom,allowedExtensions:['pdf','pptx','docx','txt','md']);if(result==null)return;setState(()=>busy=true);int done=0;final subject=ref.read(activeSubjectProvider);
 try{for(final f in result.files){if(f.path==null)continue;final parsed=await StudyParser.parseFile(File(f.path!));final post=parsed.toPost(subject);await StudyStore.savePost(post);done++;}ref.read(postsProvider.notifier).state=StudyStore.allPosts;setState(()=>status='$done file${done==1?'':'s'} transformed into study post${done==1?'':'s'} successfully.');}
 catch(e){setState(()=>status='Could not parse a file: $e');}finally{setState(()=>busy=false);}}
 @override Widget build(BuildContext context)=>AmbientBackground(child:SafeArea(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const SizedBox(height:16),const Text('Create your study feed',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800)),const SizedBox(height:8),Text('Upload notes. Keep learning offline.',style:TextStyle(color:Colors.white.withValues(alpha:.55))),const SizedBox(height:28),Glass(padding:const EdgeInsets.all(24),child:Column(children:[Container(width:86,height:86,decoration:BoxDecoration(shape:BoxShape.circle,color:const Color(0xFF9B8CFF).withValues(alpha:.14)),child:const Icon(Icons.cloud_upload_outlined,size:38,color:Color(0xFFB4A6FF)),),const SizedBox(height:16),const Text('Add study materials',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18)),const SizedBox(height:8),const Text('PDF · PowerPoint · Word · TXT · Markdown',textAlign:TextAlign.center,style:TextStyle(color:Colors.white60)),const SizedBox(height:18),FilledButton.icon(onPressed:busy?null:pick,icon:busy?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.add),label:Text(busy?'Parsing on device…':'Choose files'),style:FilledButton.styleFrom(minimumSize:const Size(double.infinity,48))),const SizedBox(height:12),Text(status,textAlign:TextAlign.center,style:const TextStyle(fontSize:12,color:Colors.white60))])),const SizedBox(height:20),const Text('What happens next',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:12),...['Content is extracted on this device — nothing is uploaded.','PDF pages and PowerPoint slides become swipeable cards.','DOCX and text notes are split into readable sections.','Posts can be bookmarked or marked mastered from the feed.'].map((t)=>Padding(padding:const EdgeInsets.only(bottom:10),child:Row(children:[const Icon(Icons.check_circle_outline,color:Color(0xFF9B8CFF),size:18),const SizedBox(width:10),Expanded(child:Text(t,style:const TextStyle(fontSize:13)))])))]))));
}
